type Cell = [number, number]; // [x, y]

function isNeighbor([x, y]: Cell, [otherX, otherY]: Cell): boolean {
  const isSameCell = x === otherX && y === otherY;
  return !isSameCell && Math.abs(otherX - x) <= 1 && Math.abs(otherY - y) <= 1;
}

function countLiveNeighbors(cell: Cell, liveCells: Cell[]): number {
  return liveCells.filter((other) => isNeighbor(cell, other)).length;
}

function survives(cell: Cell, liveCells: Cell[]): boolean {
  const liveNeighbors = countLiveNeighbors(cell, liveCells);
  return liveNeighbors === 2 || liveNeighbors === 3;
}

export function nextGeneration(liveCells: Cell[]): Cell[] {
  return liveCells.filter((cell) => survives(cell, liveCells));
}

